SELECT

FROM pur_yt_store_warning
WHERE is_deleted = 0

    AND customer_id = #{customerId}


    AND product_id = #{productId}


    AND specification_id = #{specificationId}

ORDER BY warning_time DESC

SELECT pysw.*,(select code from pro_yt_product where id = pysw.product_id) as productCode FROM pur_yt_store_warning as pysw WHERE is_deleted = 0 AND id IN
#{id}
ORDER BY warning_time DESC
